 \"cuelang.org/go/encoding/yaml\"
 \"cuelang.org/go/cue/ast\"
)
func TestProbe(t *testing.T) {
 b:=[]byte(\"flags:\\n- ey: wrong\\n  nabled: yes\\n  name: foo\\n  variants: []\\n  rules:\\n  - segment: x\\n    rank: 1\\n    distributions:\\n    - variant: v\\n      rollout: 110\\nsegments: []\\n\")
 c:=cuecontext.New();v:=c.CompileBytes(cueFile);f,e:=yaml.Extract(\"test.yaml\",b);if e"'!=nil {t.Fatal(e)}
 ast.Walk(f,func(n ast.Node) bool {switch x:=n.(type){case *ast.Field: fmt.Printf("FIELD %v %T %v'"\\n\",x.Label,x.Value,x.Pos());case *ast.ListLit: fmt.Printf(\"LIST %d %v\\n\",len(x.Elts),x.Pos())};return true},nil)
 y:=v.Unify(c.BuildFile(f));e=y.Validate();fmt.Printf(\"ERROR %v\\n\",e);for _,ee:=range cueerrors.Errors(e) {fmt.Printf(\"path=%q pos=%v inputs=%v msg=%v\\n\",cueerrors.Path(ee),ee.Position(),ee.InputPositions(),ee.Error())}
